As=[tobits(a) for a,b in pairs]; Bs=[tobits(b) for a,b in pairs]
# candidates for source position matching each target across all demos
cand={}
for r in range(6):
 for c in range(5):
  cand[(r,c)]=[(rr,cc) for rr in range(6) for cc in range(5) if all(A[rr][cc]==B[r][c] for A,B in zip(As,Bs))]
