for k,v in cand.items(): print(k,v[:10])

lookup={}; conflicts=[]
for k,(A,B) in enumerate(zip(As,Bs)):
 for r in range(6):
  x=tuple(A[r]); y=tuple(B[r]);
  if x in lookup and lookup[x][0]!=y: conflicts.append((x,lookup[x],y,k,r))
  else: lookup[x]=(y,k,r)
print('unique inputs',len(lookup),'conflicts',conflicts[:20])
for x,v in lookup.items(): print(''.join(map(str,x)),'->',''.join(map(str,v[0])))

